  align-items: center;
  justify-content: space-between;
  gap: 14px
}

.qf-heading-copy {
  display: grid;
  gap: 3px;
  flex: 1
}

.qf-eyebrow {
  font-size: 11px;
  color: var(--choice-muted);
  letter-spacing: 1px
}

.qf-editor-heading strong {
  font-size: 22px;
  font-weight: 600;
  line-height: 1.45
}

.qf-type-tag {
  padding: 4px 11px;
  border-radius: 6px;
  color: var(--choice-accent);
  background: #eee9f7;
  font-size: 12px
}

.qf-type-meta {
  display: flex;
  justify-content: space-between;
  gap: 12px;
  font-size: 12px;
  color: var(--choice-muted);
  margin: 12px 0 24px
}

.qf-type-actions {
  display: flex;
  align-items: center;
  gap: 10px;
  flex-wrap: wrap;
  margin: 24px 0 0
}

.qf-editor-actions {
  margin: 18px 0 6px;
  padding-bottom: 20px;
  border-bottom: 1px solid var(--choice-line)
