.qf-choice-editor button,
.qf-choice-practice button,
.qf-choice-editor select {
  font: 13px/1.5 Arial, "Microsoft YaHei", sans-serif;
  min-height: 36px;
  padding: 7px 13px;
  border: 1px solid #ded7e9;
  border-radius: 8px;
  background: white;
  color: var(--choice-accent);
  cursor: pointer;
  transition: background .15s, border-color .15s;
