.qf-choice-editor button.primary:hover,
.qf-choice-practice button.primary:hover {
  background: #6a539d
}

.qf-choice-editor button:disabled,
.qf-choice-practice button:disabled {
  opacity: .45;
  cursor: default
}

.qf-choice-editor button.danger,
.qf-choice-editor button.quiet-danger {
  color: #bd5264
}

.qf-choice-editor button:focus-visible,
.qf-choice-practice button:focus-visible,
.qf-choice-editor select:focus-visible {
  outline: 2px solid #ad97d5;
  outline-offset: 3px
}

.qf-editor-section {
  margin-top: 24px
}

.qf-field {
  display: grid;
  gap: 10px
}

.qf-field-title,
.qf-section-heading strong,
.qf-type-sources>strong {
  font-size: 14px;
  font-weight: 600
}

.qf-section-heading {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  margin-bottom: 10px
}

.qf-choice-editor textarea,
.qf-choice-editor input[type=number],
.qf-source-input input {
  width: 100%;
  font: inherit;
  line-height: 1.65;
  padding: 11px 13px;
  border: 1px solid #dfd9e8;
  border-radius: 8px;
  background: #fff;
  color: inherit;
  outline: none;
}

.qf-choice-editor textarea {
  resize: vertical;
  display: block
}

.qf-choice-editor textarea:focus,
.qf-choice-editor input[type=number]:focus,
.qf-source-input input:focus {
  border-color: #a18ac6;
  box-shadow: 0 0 0 3px #7962ad0d
}

.qf-edit-options {
  display: grid;
  gap: 10px;
  margin-top: 14px
}

.qf-choice-edit-row {
  display: grid;
  grid-template-columns: 20px 28px minmax(0, 1fr) auto;
  align-items: center;
  gap: 10px;
  padding: 9px 10px;
