.qf-choice-edit-row textarea {
  padding: 8px 10px;
  min-height: 42px;
  font-size: 14px
}

.qf-choice-edit-row button {
  padding: 6px 8px;
  min-height: 32px;
  border-color: transparent;
  background: transparent;
  color: var(--choice-muted);
  font-size: 12px
