.qf-choice-edit-row button:hover {
  color: #bd5264;
  background: #fff1f3;
  border-color: transparent
}

.qf-score-input {
  display: flex;
  align-items: center;
  gap: 10px;
  color: var(--choice-muted);
  font-size: 13px
}

.qf-score-input input[type=number] {
  width: 112px;
  color: #302c3b
}

.qf-analysis-editor {
  margin-top: 12px
}

.qf-choice-prompt {
  margin: 0 0 14px;
  white-space: pre-wrap;
  overflow-wrap: anywhere;
  font-size: 18px;
  font-weight: 500;
  line-height: 1.8
}

.qf-choice-hint {
  margin-bottom: 14px !important
}

.qf-choice-options {
  display: grid;
  gap: 10px
}

.qf-choice-option {
  display: flex;
  align-items: flex-start;
  gap: 12px;
  padding: 14px 15px;
  border: 1px solid #eeeaf2;
  border-radius: 10px;
  background: #fcfbfd;
  cursor: pointer;
  transition: background .15s, border-color .15s
}

.qf-choice-option:hover {
  background: #f8f5fc;
  border-color: #d8cde7
}

.qf-choice-option.selected {
  background: var(--choice-soft);
  border-color: #d4c5e7
}

.qf-choice-option .qf-option-text {
  flex: 1;
  min-width: 0;
  white-space: pre-wrap;
  overflow-wrap: anywhere
}

.qf-choice-option input,
.qf-choice-edit-row>input {
  appearance: none;
  -webkit-appearance: none;
  width: 20px;
  height: 20px;
  flex: none;
  position: relative;
  border: 1.5px solid #cec7d6;
  border-radius: 50%;
  margin: 2px 0 0;
  background: white;
  cursor: pointer;
}

.qf-choice-option input[type=checkbox],
.qf-choice-edit-row>input[type=checkbox] {
  border-radius: 5px
}

.qf-choice-option input:checked,
.qf-choice-edit-row>input:checked {
  border-color: var(--choice-accent)
}

.qf-choice-option input:checked:after,
.qf-choice-edit-row>input:checked:after {
  content: "";
  position: absolute;
  inset: 4px;
  background: var(--choice-accent);
  border-radius: 50%
}

.qf-choice-option input[type=checkbox]:checked:after,
.qf-choice-edit-row>input[type=checkbox]:checked:after {
  content: "✓";
  inset: -4px 0 0;
  color: var(--choice-accent);
  background: transparent;
  font-size: 19px;
  text-align: center
}

.qf-choice-option input:focus-visible,
.qf-choice-edit-row>input:focus-visible {
  outline: 2px solid #ad97d5;
  outline-offset: 3px
}

.qf-choice-option input:disabled {
  opacity: 1;
  cursor: default
}

.qf-choice-option.correct {
  background: #edf7f3;
  border-color: #cce8dd;
  color: #13876d
}

.qf-choice-option.incorrect {
  background: #fff0f2;
  border-color: #f2d3db;
  color: #c64b63
}

.qf-choice-option.correct .qf-option-letter {
  color: #13876d
}

.qf-choice-option.incorrect .qf-option-letter {
  color: #c64b63
}

.qf-option-feedback {
  font-size: 11px;
  line-height: 24px;
  flex: none;
  white-space: nowrap
}

.qf-inline-confirm {
  display: flex;
  align-items: center;
  gap: 10px;
  flex-wrap: wrap;
  padding: 14px 16px;
  margin-top: 16px;
  background: var(--choice-soft);
  border: 1px solid #e0d6ed;
  border-radius: 10px;
  font-size: 13px
}

.qf-inline-confirm>span {
  flex: 1;
  min-width: 180px
}

.qf-result-panel {
  margin-top: 26px;
  padding: 20px;
  border: 1px solid var(--choice-line);
  border-radius: 12px;
  background: #fcfbfd
}

.qf-result-heading {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  flex-wrap: wrap
}

.qf-result-heading p {
  margin: 0
}

.qf-result-heading [data-verdict] {
  font-size: 15px;
  font-weight: 600
}

.qf-result-heading .correct {
  color: #13876d
}

.qf-result-heading .incorrect {
  color: #c64b63
}

.qf-result-score {
  font-size: 13px;
  color: var(--choice-accent);
  padding: 4px 10px;
  background: #eee9f7;
  border-radius: 6px
}

.qf-correct-answer {
  margin: 12px 0 0;
  font-size: 13px;
  color: #6a6178
}

.qf-result-analysis {
  border-top: 1px solid var(--choice-line);
  padding-top: 16px;
  margin-top: 16px
}

.qf-result-analysis>strong {
  font-size: 13px;
  font-weight: 600
}

.qf-result-analysis [data-analysis] {
  margin-top: 8px;
  overflow-wrap: anywhere
}

.qf-type-sources {
  border-top: 1px solid var(--choice-line);
  padding-top: 18px;
  margin-top: 26px;
  font-size: 13px
}

.qf-type-source {
  display: flex;
  align-items: center;
  flex-wrap: wrap;
  gap: 8px;
  margin-top: 10px
}

.qf-type-source>button:first-child {
  max-width: 100%;
  overflow-wrap: anywhere;
  text-align: left
}

.qf-type-source>.muted {
  flex: 1
}

.qf-source-input {
  display: flex;
  align-items: center;
  gap: 10px;
  margin-top: 12px
}

.qf-source-input input {
  flex: 1;
  min-width: 0;
  font-size: 13px
}

.qf-source-input button {
  flex: none
}

.qf-choice-practice [data-stage-note] {
  margin-top: 24px;
  font-size: 11px;
  line-height: 1.7
}

@media(max-width:520px) {
  .qf-editor-heading {
    flex-wrap: wrap
  }

  .qf-heading-copy {
    min-width: 130px
  }

  .qf-editor-heading strong {
    font-size: 20px
  }

  .qf-choice-edit-row {
    grid-template-columns: 20px 22px minmax(0, 1fr) auto;
    gap: 6px;
    padding: 8px
  }

  .qf-choice-edit-row button {
    padding: 6px 3px
  }

  .qf-choice-option {
    padding: 12px 10px;
    gap: 8px
  }

  .qf-option-feedback {
    font-size: 10px
  }

  .qf-result-panel {
    padding: 16px
  }

  .qf-choice-prompt {
    font-size: 17px
  }
}
